const seen = [];
const registry = new FinalizationRegistry((label) => seen.push(label));
const invoice = { id: 9 };
const first = new WeakRef(invoice);
const second = new WeakRef(invoice);

registry.register(invoice, { label: "inv-9" }, invoice);
console.log(first.deref() === second.deref());
console.log(registry.unregister({ id: 9 }));
console.log(registry.unregister(invoice));
console.log(seen.length);

try {
  registry.register(invoice, "late", "inv-9");
} catch (error) {
  console.log(error.name);
}
